    """Pull out --dir (anywhere); return (directory, remaining args)."""
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a folder")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    return directory, rest


def _is_option(arg: str) -> bool:
    return arg.startswith("--") or (arg.startswith("-") and len(arg) > 1)


def _parse_args(argv):
    directory, rest = _split_args(argv)
    if not rest:
        raise UsageError("no command given")
    command, args = rest[0], rest[1:]
    if command not in _FILES:
        raise UsageError("unknown command %r" % command)

    options = {"json": False, "format": "text"}
    if command in _PLAIN_COMMANDS:
        positionals = list(args)
    else:
        positionals = []
        i = 0
        while i < len(args):
            arg = args[i]
            if arg == "--json" and command in _JSON_COMMANDS:
                options["json"] = True
            elif command == "report" and arg == "--format":
                if i + 1 >= len(args):
                    raise UsageError("--format needs a value")
                options["format"] = args[i + 1]
                i += 1
            elif command == "report" and arg.startswith("--format="):
                options["format"] = arg[len("--format="):]
            elif _is_option(arg):
                raise UsageError("unknown option %r" % arg)
            else:
                positionals.append(arg)
            i += 1
        if command == "report" and options["format"] not in ("text", "csv", "json"):
            raise UsageError("bad --format %r (text, csv or json)" % options["format"])

    low, high = _POSITIONALS[command]
    if not low <= len(positionals) <= high:
        raise UsageError("wrong number of arguments for %s" % command)

    date = None
    if command in ("receive", "ship"):
        date = parse_date(positionals[0])
        if date is None:
            raise UsageError("bad date %r (want YYYY-MM-DD)" % positionals[0])
        if len(positionals) == 4:
            try:
                positionals[3].encode("utf-8")
            except UnicodeEncodeError:
                raise UsageError("note is not valid UTF-8") from None
    elif command == "fulfil":
        date = parse_date(positionals[1])
        if date is None:
            raise UsageError("bad date %r (want YYYY-MM-DD)" % positionals[1])
    return command, directory, positionals, options, date


