def _read(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        if required:
            raise FileProblem("%s: file not found" % name) from None
        return b""
    except OSError as err:
        raise FileProblem("%s: %s" % (name, err.strerror or err)) from None
    try:
        raw.decode("utf-8")
    except UnicodeDecodeError:
        raise FileProblem("%s: not valid UTF-8" % name) from None
    return raw


def _parse(name, func, *args):
    try:
        return func(*args)
    except ParseError as err:
        raise Refusal("%s: %s" % (name, err)) from None


def _append(directory, existing: bytes, text: str):
    prefix = b"\n" if existing and not existing.endswith(b"\n") else b""
    try:
        with open(os.path.join(directory, MOVEMENTS), "ab") as handle:
            handle.write(prefix + text.encode("utf-8"))
    except OSError as err:
        raise FileProblem("%s: %s" % (MOVEMENTS, err.strerror or err)) from None


